import 'dart:math' as math;

import 'package:poker_protocol/poker_protocol.dart';

/// Every sound effect of the app. The clips are original work generated by `tool/sounds`, bundled
/// as `assets/sounds/<clip>.wav` (licence: `assets/sounds/README.md`). Where a cue has several
/// clips they are played in turn, so a run of calls does not sound like one sample on repeat.
enum SoundCue {
  /// It is your turn: three rising notes.
  turn(['turn']),

  /// Somebody checked: two knuckle taps on felt.
  check(['check']),

  /// A call or a bet: a few chips set down.
  call(['call_1', 'call_2', 'call_3']),

  /// A raise: a bigger stack of chips.
  raise(['raise_1', 'raise_2']),

  /// All in: a long cascade of chips on a low swell.
  allIn(['all_in']),

  /// A fold: a card slid away.
  fold(['fold']),

  /// Your two cards arrived.
  deal(['deal']),

  /// A new hand starts at the table: the deck is riffled.
  shuffle(['shuffle']),

  /// The flop: three cards turned over.
  flop(['flop']),

  /// The turn or the river: one card turned over.
  street(['street']),

  /// Showdown: the hands are turned over.
  reveal(['reveal']),

  /// You won the pot.
  win(['win']),

  /// Somebody else won the pot: the chips are drawn in.
  potWon(['pot_won']),

  /// You are out of the game.
  out(['out']),

  /// You won the game.
  gameWon(['game_won']),

  /// The blinds went up.
  levelUp(['level_up']),

  /// Somebody sat down.
  join(['join']),

  /// Somebody left the table.
  leave(['leave'])
  ;

  const SoundCue(this.clips);

  /// File names (without `.wav`) of this cue's clips.
  final List<String> clips;

  /// Asset path of the clip with this file name.
  static String assetOf(String clip) => 'assets/sounds/$clip.wav';
}

/// Who is listening. Phones sit together at one table, so each kind of device plays only what is
/// its own to play: a table that every phone repeated would be noise.
enum SoundAudience {
  /// A single-player game: everything is heard on the one phone.
  solo,

  /// The host's device or a spectator: the table's sounds (chips, cards) and the personal ones.
  table,

  /// A seated guest: only its own cards, its own actions and its own wins and losses.
  seat,
}

/// Turns the live messages of one room into the sounds to play (no poker rules here: it only
/// notices what the server's view changed to).
///
/// A `SNAPSHOT` only sets the baseline and is silent, and so is everything it repeats (the
/// `HOLE_CARDS` the server resends after each of them): coming back to a table must not replay it.
/// Every cue fires once per change, so a repeated update is harmless.
class SoundTracker {
  bool _primed = false;
  int _hand = -1;
  int _dealtHand = -1;
  int _street = 0;
  bool _revealed = false;
  bool _resulted = false;
  Set<String> _seats = const <String>{};
  Set<String> _finished = const <String>{};
  int? _smallBlind;
  WirePhase _phase = WirePhase.lobby;
  Map<String, int> _chips = const <String, int>{};

  /// The last view, for the audience of an action: actions arrive between updates.
  RoomView? _view;

  /// Forgets the room (a new session starts, or the user left).
  void reset() {
    _primed = false;
    _hand = -1;
    _dealtHand = -1;
    _street = 0;
    _revealed = false;
    _resulted = false;
    _seats = const <String>{};
    _finished = const <String>{};
    _smallBlind = null;
    _phase = WirePhase.lobby;
    _chips = const <String, int>{};
    _view = null;
  }

  /// The sounds for [message], newest state included. [me] is this device's player id and
  /// [isHost] says whether it hosts the room.
  List<SoundCue> onMessage(ServerMessage message, {required String? me, required bool isHost}) {
    switch (message) {
      case Snapshot():
        _baseline(message.view);
        _dealtHand = math.max(_dealtHand, message.view.handNumber);
        return const <SoundCue>[];
      case StateUpdate():
        if (!_primed) {
          _baseline(message.view);
          return const <SoundCue>[];
        }
        return _change(message.view, me, isHost);
      case HoleCards():
        if (!_primed || message.handNumber <= _dealtHand) {
          _dealtHand = math.max(_dealtHand, message.handNumber);
          return const <SoundCue>[];
        }
        _dealtHand = message.handNumber;
        return const <SoundCue>[SoundCue.deal];
      case ActionPerformed():
        return _action(message, me, isHost);
      default:
        return const <SoundCue>[];
    }
  }

  /// The audience of a device, from the view it sees.
  static SoundAudience audienceOf(RoomView view, {required String? me, required bool isHost}) {
    if (view.blinds != null) return SoundAudience.solo;
    final seated = me != null && view.seats.any((seat) => seat.playerId == me);
    return seated && !isHost ? SoundAudience.seat : SoundAudience.table;
  }

  void _baseline(RoomView view) {
    _primed = true;
    _view = view;
    _hand = view.handNumber;
    _street = _streetOf(view);
    _revealed = view.reveals.isNotEmpty;
    _resulted = view.result != null;
    _seats = {for (final seat in view.seats) seat.playerId};
    _finished = {for (final finish in view.finishOrder) finish.playerId};
    _smallBlind = view.blinds?.smallBlind;
    _phase = view.phase;
    _chips = _chipsOf(view);
  }

  static Map<String, int> _chipsOf(RoomView view) => {for (final seat in view.seats) seat.playerId: seat.chips};

  /// 0 before the flop, then the number of community cards: 3, 4 or 5. Read from the board and
  /// from the phase, because a room that deals real cards never fills the board.
  static int _streetOf(RoomView view) {
    final fromPhase = switch (view.phase) {
      WirePhase.flop => 3,
      WirePhase.turn => 4,
      WirePhase.river => 5,
      _ => 0,
    };
    return math.max(fromPhase, view.board.length.clamp(0, 5));
  }

  List<SoundCue> _change(RoomView view, String? me, bool isHost) {
    _view = view;
    final audience = audienceOf(view, me: me, isHost: isHost);
    final cues = <SoundCue>[];
    final listensToTable = audience != SoundAudience.seat;

    if (view.handNumber != _hand) {
      final started = view.handNumber > _hand && view.phase != WirePhase.lobby;
      _hand = view.handNumber;
      _street = 0;
      _revealed = false;
      _resulted = false;
      // A single-player game deals to you (the deal cue), so the table's riffle is only for a table.
      if (started && audience == SoundAudience.table) cues.add(SoundCue.shuffle);
    }

    final street = _streetOf(view);
    if (street > _street) {
      if (listensToTable) cues.add(_street < 3 && street >= 3 ? SoundCue.flop : SoundCue.street);
      _street = street;
    }

    // The hands are shown when the view lists them, or, in a room that deals real cards (the view
    // lists none), when the hand reaches its showdown.
    var reveal = false;
    if (!_revealed && (view.reveals.isNotEmpty || view.phase == WirePhase.showdown)) {
      _revealed = true;
      reveal = listensToTable;
    }

    // The pot is paid when the view carries the result, or, without one (real cards), when the hand
    // ends: then this phone won if its own stack grew in that very update.
    SoundCue? pot;
    final result = view.result;
    final handEnded = view.phase == WirePhase.nextHandPrep && _phase != WirePhase.nextHandPrep;
    if (!_resulted && (result != null || handEnded)) {
      _resulted = true;
      final won = me != null && (result != null ? result.pots.any((p) => p.winnerPlayerIds.contains(me)) : _stackGrew(view, me));
      if (won) {
        pot = SoundCue.win;
      } else if (listensToTable) {
        pot = SoundCue.potWon;
      }
    }

    SoundCue? finish;
    for (final entry in view.finishOrder) {
      if (_finished.contains(entry.playerId)) continue;
      if (entry.playerId == me) finish = entry.place == 1 ? SoundCue.gameWon : SoundCue.out;
    }
    _finished = {for (final entry in view.finishOrder) entry.playerId};

    // One closing sound per moment: the end of the game beats the pot, the pot beats the reveal.
    if (finish != null) {
      cues.add(finish);
    } else if (pot != null) {
      cues.add(pot);
    } else if (reveal) {
      cues.add(SoundCue.reveal);
    }

    final small = view.blinds?.smallBlind;
    if (small != null && _smallBlind != null && small > _smallBlind!) cues.add(SoundCue.levelUp);
    _smallBlind = small ?? _smallBlind;

    final seats = {for (final seat in view.seats) seat.playerId};
    if (audience == SoundAudience.table) {
      if (seats.difference(_seats).any((id) => id != me)) cues.add(SoundCue.join);
      if (_seats.difference(seats).any((id) => id != me)) cues.add(SoundCue.leave);
    }
    _seats = seats;
    _phase = view.phase;
    _chips = _chipsOf(view);
    return cues;
  }

  bool _stackGrew(RoomView view, String me) {
    final before = _chips[me];
    if (before == null) return false;
    return view.seats.any((seat) => seat.playerId == me && seat.chips > before);
  }

  List<SoundCue> _action(ActionPerformed action, String? me, bool isHost) {
    final view = _view;
    if (!_primed || view == null) return const <SoundCue>[];
    // Your own action is heard on your own device; the others' only where the table is.
    if (action.playerId != me && audienceOf(view, me: me, isHost: isHost) == SoundAudience.seat) return const <SoundCue>[];
    final aggressive = action.kind == ActionKind.call || action.kind == ActionKind.bet || action.kind == ActionKind.raise;
    if (action.allIn && aggressive) return const <SoundCue>[SoundCue.allIn];
    return switch (action.kind) {
      ActionKind.fold => const <SoundCue>[SoundCue.fold],
      ActionKind.check => const <SoundCue>[SoundCue.check],
      ActionKind.call || ActionKind.bet => const <SoundCue>[SoundCue.call],
      ActionKind.raise => const <SoundCue>[SoundCue.raise],
      ActionKind.unknown => const <SoundCue>[],
    };
  }
}
